commandLine.original:
ssh -p 2222 root@34.47.5.151 "cd /home/terrainsmauricie/server && node -e \"
const sharp = require('sharp');
console.log('sharp versions:', JSON.stringify(sharp.versions, null, 2));
console.log('---');
// Test a simple webp conversion
sharp(Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64'))
  .toFormat('webp')
  .toBuffer()
  .then(b => console.log('WebP encode OK, size:', b.length))
  .catch(e => console.error('WebP encode FAILED:', e.message));
sharp(Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64'))
  .webp({ quality: 80 })
  .toBuffer()
  .then(b => console.log('WebP via .webp() OK, size:', b.length))
  .catch(e => console.error('WebP via .webp() FAILED:', e.message));
// Test heif
sharp(Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64'))
  .heif({ compression: 'av1' })
  .toBuffer()
  .then(b => console.log('HEIF AV1 OK, size:', b.length))
  .catch(e => console.error('HEIF AV1 FAILED:', e.message));
sharp(Buffer.from('R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7', 'base64'))
  .heif({ compression: 'hevc' })
  .toBuffer()
  .then(b => console.log('HEIF HEVC OK, size:', b.length))
  .catch(e => console.error('HEIF HEVC FAILED:', e.message));
\" 2>&1"

